from pathlib import Path
from datetime import datetime
import json,hashlib,shutil,uuid,os
root=Path(r'E:\ntnu_mesh_optimization_20261030')
p=root/'plan.json'; rb=root/'AUTONOMOUS_RECOVERY_PROMPT.md'; w=root/'wave_surface_only'/'plan.json'
old=p.read_bytes(); m=json.loads(old.decode('utf-8-sig')); oldrb=rb.read_bytes()
assert hashlib.sha256(oldrb).hexdigest()==m['recovery_policy']['runbook_sha256'],'Runbook mismatch'
now=datetime.now().astimezone();stamp=now.strftime('%Y%m%d_%H%M%S')
backup=root/('policy_before_parallel_'+stamp);backup.mkdir()
for f in (p,rb,w):shutil.copy2(f,backup/(('wave_' if f==w else '')+f.name))
policy={'authorized':True,'authorization':'User explicitly allows parallel mesh calculations if they do not drastically increase M12 time per step.','maximum_auxiliary_solvers':1,'first_auxiliary_backend':'CPU only, 2 workers, BELOW_NORMAL priority; never a second GPU solve','allow_growth_to_4_workers_after_measured_pass':True,'initial_pilot_max_steps':60,'initial_pilot_solver_budget_s':600,'M12_slowdown_fraction_soft_limit':0.15,'performance_threshold_is_project_choice_not_ITTC':True,'comparison':'Measure before/after in same M12 continuation using wall_seconds increments. Baseline median of >=200 consecutive physical steps; use two independent windows of >=30 newly completed M12 steps and assess persistent slowdown. Log full wall-time and save overhead separately.','automatic_action_on_slowdown':'Graceful STOP for AUXILIARY only; no M12 stop, no M12 affinity/priority/configuration changes. Also stop auxiliary on stale M12 history, primary stage change, insufficient RAM/disk or explicit pause.','minimum_free_RAM_GiB':16,'minimum_free_C_GiB':15,'minimum_free_E_GiB':25,'respect_existing_control_locks':True,'all_new_auxiliary_files':'E:\\ntnu_mesh_optimization_20261030\\parallel_cpu_20261031','first_pilot':'Isolated M10 calm-water performance test on copied verified pilot final.sim, same dt=0.0001 and 10 inner iterations; no acceptance claim and no modification to existing GPU queue.','later_scope':'One independently configured no-foil wave-surface trial on CPU at target dt=0.001 may run after resource pilot passes and upstream calm-first setup is verified. Preserve existing held C01/foil-wave and HF; new no-foil test is separate authorized scope, not a release of their hold.'}
m['updated_at']=now.isoformat();m['parallel_execution']=policy;m['limits']['no_parallel_solver']=False
m['limits']['parallel_exception_policy']='parallel_execution overrides prior blanket ban; never unlimited concurrency'
m['noon_M12_review']={'time_local':'2026-10-31T12:00:00+01:00','purpose':'User review checkpoint for whether to end expensive M12 and move on, even if internal component thresholds remain unmet.','no_automatic_extension_past_noon':True,'automatic_kill_at_noon':False,'automatic_acceptance_or_criteria_change':False,'readout':'Actual CL/CD means and drift, longer windows, pressure/viscous absolute contributions normalized by total CD, primary and auxiliary cost, saved checkpoints and recommendation. A stopped result must retain its true not-stabilized status.'}
m['criterion_provenance']={'kind':'project-defined heuristic, not an ITTC numerical threshold','existing':'0.5% own-mean normalization for all four quantities, 0.2s adjacent windows, two passes; mesh agreement 1% is also project choice','references':['ITTC 7.5-03-02-03 (2024) section 3.8','ITTC 7.5-03-02-04 (2024) section 2.7','ITTC 7.5-03-01-01 Rev05 (2024) section 3.3'],'review':'Discuss primary quantities CL and CD and absolute pressure/viscous drift contributions; do not silently alter active solver criteria or reclassify old failures.'}
text=oldrb.decode('utf-8-sig')
section='''\n## Latest user authorization, 31 October 2026: bounded parallel CPU and noon review\nThis section overrides earlier blanket bans on parallel solvers only for one isolated auxiliary CPU job. Read plan.json parallel_execution. Start with two CPU workers, below-normal priority, no second GPU job, copied verified input and independent E: output/lock. Keep M12 and its queue, locks, allocation and original files unchanged. Measure M12 median seconds/step before and during. If persistent slowdown exceeds 15% in two independent windows, gracefully stop only the auxiliary. The 15% performance budget is an operational choice, not ITTC. Preserve STOP_ALL, deliberate user pause, HF and the existing held C01/foil-wave campaign. Newly authorized no-foil diagnostics must be independent and do not lift the old wave hold. No duplicate launches; verify owned process tree and resources. Main M12 is reviewed at 12:00 Europe/Oslo on 31 October 2026. Do not automatically extend/restart M12 beyond that time; do not kill or certify it just because noon arrives. Report current evidence and recommend whether to save/end or proceed. Existing 0.5% component-own-relative criteria are project heuristics, not mandatory ITTC thresholds, and remain unmodified until a documented scientific decision.\n'''
assert '## Latest user authorization, 31 October 2026: bounded parallel CPU' not in text
newrb=(text+section).encode('utf-8');m['recovery_policy']['runbook_sha256']=hashlib.sha256(newrb).hexdigest()
wm=json.loads(w.read_text(encoding='utf-8-sig'));wm['updated_at']=now.isoformat();wm['do_not_run_solver_concurrently_with_M12']=False;wm['parallel_policy_reference']='parent plan.json parallel_execution; maximum one CPU auxiliary with M12 protection'
wm['timestep_priority']['resource_safety']='Bounded separate CPU trial may coexist with M12 only after measured slowdown pilot passes; target waves dt=0.001 s, calm first, then inlet wave. Do not use second GPU or touch old held C01/foil-wave.'
for f,data in ((rb,newrb),(w,(json.dumps(wm,ensure_ascii=False,indent=2)+'\n').encode('utf-8')),(p,(json.dumps(m,ensure_ascii=False,indent=2)+'\n').encode('utf-8'))):
 tmp=f.with_name(f.name+'.'+uuid.uuid4().hex+'.tmp');tmp.write_bytes(data);os.replace(tmp,f)
assert hashlib.sha256(rb.read_bytes()).hexdigest()==json.loads(p.read_text(encoding='utf-8'))['recovery_policy']['runbook_sha256']
with (root/'decisions.jsonl').open('a',encoding='utf-8') as f:f.write(json.dumps({'at':now.isoformat(),'event':'user_parallel_permission_noon_M12_review','policy':policy,'no_solver_change':True,'backup':str(backup)},ensure_ascii=False)+'\n')
(root/'parallel_cpu_20261031').mkdir(exist_ok=True)
print(json.dumps({'updated':True,'backup':str(backup),'parallel_workers_initial':2,'max_slowdown_fraction':.15,'review_at':m['noon_M12_review']['time_local'],'runbook_hash_verified':True,'solver_changed':False}))
